CREATE TABLE signal_company_members(company_id integer NOT NULL REFERENCES signal_companies(id),user_id integer NOT NULL REFERENCES signal_users(id),appointed_by integer NOT NULL REFERENCES signal_users(id),active boolean NOT NULL DEFAULT true,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,user_id));
CREATE TABLE signal_guest_permissions(resume_id integer PRIMARY KEY REFERENCES signal_candidate_resumes(id),user_id integer NOT NULL REFERENCES signal_users(id),allowed boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER signal_guest_permission_epoch AFTER INSERT OR UPDATE OR DELETE ON signal_guest_permissions FOR EACH STATEMENT EXECUTE FUNCTION signal_bump_professional_epoch();
CREATE TABLE signal_shared_selections(id uuid PRIMARY KEY,company_id integer NOT NULL REFERENCES signal_companies(id),created_by integer NOT NULL REFERENCES signal_users(id),context_type text NOT NULL CHECK(context_type IN ('job','need')),context_id integer NOT NULL,context_revision integer NOT NULL,public_purpose text NOT NULL,items jsonb NOT NULL,member_ids jsonb NOT NULL,token_hash text,expires_at timestamptz NOT NULL,revoked_at timestamptz,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX signal_share_company_idx ON signal_shared_selections(company_id,created_at);
CREATE TABLE signal_share_comments(id uuid PRIMARY KEY,share_id uuid NOT NULL REFERENCES signal_shared_selections(id),candidate_id integer NOT NULL REFERENCES signal_users(id),resume_id integer NOT NULL REFERENCES signal_candidate_resumes(id),resume_revision integer NOT NULL,author text NOT NULL,reaction text NOT NULL CHECK(reaction IN ('consider','discuss','pass')),note text NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX signal_share_comment_idx ON signal_share_comments(share_id,created_at);
CREATE FUNCTION signal_preserve_share_snapshot() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.items IS DISTINCT FROM OLD.items OR NEW.member_ids IS DISTINCT FROM OLD.member_ids OR NEW.context_id<>OLD.context_id OR NEW.context_type<>OLD.context_type OR NEW.context_revision<>OLD.context_revision OR NEW.company_id<>OLD.company_id OR NEW.public_purpose<>OLD.public_purpose OR NEW.token_hash IS DISTINCT FROM OLD.token_hash OR NEW.expires_at<>OLD.expires_at THEN RAISE EXCEPTION 'shared selection composition is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER signal_share_snapshot_immutable BEFORE UPDATE ON signal_shared_selections FOR EACH ROW EXECUTE FUNCTION signal_preserve_share_snapshot();
